const data = $input.first().json;
const nome = data.nome || 'artista';
const slug = nome.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove accents
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
const token = Array.from({length: 32}, () => 
  'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]
).join('');

// Weekly working hours: seg..dom -> arrays of "HH:MM-HH:MM" shift blocks.
const weekdays = ['seg','ter','qua','qui','sex','sab','dom'];
const working_hours = {};
weekdays.forEach(d => {
  const raw = (data['working_' + d] || '').trim();
  if (raw === '') return;
  working_hours[d] = raw.split(',').map(s => s.trim()).filter(Boolean);
});

// AI active window: {start, end} or null (null = always active).
let ai_active_hours = null;
if ((data.ai_active_start || '').trim() !== '' && (data.ai_active_end || '').trim() !== '') {
  ai_active_hours = {
    start: data.ai_active_start.trim(),
    end: data.ai_active_end.trim(),
  };
}

// Pricing CSV: one line per row "placement,zone,price_cents,duration_min,buffer_min".
const pricing_rows = [];
String(data.pricing_csv || '').split(/\r?\n/).forEach(line => {
  const parts = line.split(',').map(s => s.trim()).filter(s => s !== '');
  if (parts.length < 3) return;
  pricing_rows.push({
    placement: parts[0],
    body_zone: parts[1],
    table_price: parseInt(parts[2], 10),
    session_duration_min: parts[3] ? parseInt(parts[3], 10) : 120,
    buffer_min: parts[4] ? parseInt(parts[4], 10) : 30,
  });
});

return [{
  json: {
    ...data,
    wa_session_slug: slug + '-' + Date.now().toString(36),
    onboarding_token: token,
    display_name: nome,
    working_hours: working_hours,
    ai_active_hours: ai_active_hours,
    pricing_rows: pricing_rows,
  }
}];

const artist = $('INSERT Artist').first().json;
const pricing = $('Generate Slug+Token').first().json.pricing_rows || [];

// Always emit at least one item so the flow continues even with no pricing rows;
// the INSERT Pricing query no-ops on a NULL placement.
if (pricing.length === 0) {
  return [{ json: { artist_id: artist.id, placement: null } }];
}

return pricing.map(row => ({
  json: {
    artist_id: artist.id,
    placement: row.placement,
    body_zone: row.body_zone,
    table_price: row.table_price,
    session_duration_min: row.session_duration_min,
    buffer_min: row.buffer_min,
  }
}));
